-- مطابقة المنصة الجديدة لورقة «القيود» في ملف «نظام الجدول المدرسي» (2026-10-13، خطة اعتمدها صاحب المنصة)
-- القسم الثالث 61 صفاً = 1001–1057 + 1112–1115؛ القسمان الأول والثاني = بارامترات 1201– (صف لكل خانة).
begin;
delete from constraints where target_type <> '' and id not between 1001 and 1057 and id not in (1105,1106,1107,1108,1109);
update constraints set value = '1، 2، 3', text = 'الحصص المسموحة: مأمون الخطيب — 1، 2، 3' where id = 1016;
update constraints set duration = 'ثابتة', sheet_state = case when active then 'مسجّل' else 'خامل' end where id between 1001 and 1057;
commit;
